.sc6{
  --green:#2D661B; --green-d:#1F3A17; --green-s:#E9EFE4;
  --gold:#CFAB62; --gold-s:#F6EEDC;
  --cream:#F7F4EE; --line:#E4DED2;
  --ink:#2B2925; --text:#5E5A52; --muted:#8F887B;
  --title:"Chelmu Rounded","Fredoka One","Trebuchet MS",sans-serif;
  --body:"Source Sans Pro","Source Sans 3","Segoe UI",Arial,sans-serif;
  --wrap:1120px; --pad:clamp(64px,8vw,104px); --nav:68px;
  font-family:var(--body); font-size:18px; line-height:1.6; color:var(--text); background:#fff;
  -webkit-font-smoothing:antialiased;
}
.sc6 *,.sc6 *::before,.sc6 *::after{box-sizing:border-box}
.sc6 img{display:block;max-width:100%}
.sc6 a{color:inherit;text-decoration:none}
.sc6 h1,.sc6 h2,.sc6 h3,.sc6 h4,.sc6 p,.sc6 ul,.sc6 figure{margin:0;padding:0}
.sc6 ul{list-style:none}
.sc6 h1,.sc6 h2,.sc6 h3{font-family:var(--title);font-weight:400;color:var(--ink);letter-spacing:0;text-transform:none}
.sc6 [hidden]{display:none!important}
html{scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.sc6 section,.sc6-anchor{scroll-margin-top:calc(var(--nav) + 12px)}
.sc6-wrap{width:min(var(--wrap),100% - 40px);margin-inline:auto}
.sc6-sec{padding:var(--pad) 0}
.sc6-sec--cream{background:var(--cream)}
.sc6-head{max-width:680px;margin:0 auto clamp(36px,5vw,56px);text-align:center}
.sc6-head h2{font-size:clamp(30px,4vw,44px);line-height:1.15;text-wrap:balance}
.sc6-head p{margin-top:14px;font-size:clamp(17px,1.5vw,19px)}
.sc6-head:has(.sc6-oneline){max-width:none}
@media (min-width:900px){.sc6 .sc6-oneline{white-space:nowrap}}

/* butoane */
.sc6-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:14px 28px;border-radius:6px;border:2px solid var(--green);background:var(--green);color:#fff!important;font-family:var(--title);font-size:17px;line-height:1.1;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
.sc6-btn:hover{background:var(--green-d);border-color:var(--green-d)}
.sc6-btn--light{background:#fff;color:var(--green)!important;border-color:#fff}
.sc6-btn--light:hover{background:var(--green-s);border-color:var(--green-s)}
.sc6-btn--line{background:transparent;color:var(--green)!important}
.sc6-btn--line:hover{background:var(--green-s);border-color:var(--green)}
.sc6-btn--ghost{background:transparent;color:#fff!important;border-color:rgba(255,255,255,.6)}
.sc6-btn--ghost:hover{background:var(--green);border-color:var(--green);color:#fff!important}
.sc6-btn:focus-visible,.sc6 a:focus-visible,.sc6 button:focus-visible{outline:3px solid var(--gold);outline-offset:3px}
.sc6-btn svg{width:18px;height:18px;flex:none}

/* ===== meniu ===== */
.sc6-nav{position:fixed;inset:0 0 auto 0;z-index:60;height:var(--nav);display:flex;align-items:center;background:rgba(31,58,23,.0);transition:background .3s,box-shadow .3s}
.admin-bar .sc6-nav{top:32px}
@media (max-width:782px){.admin-bar .sc6-nav{top:46px}}
.sc6-nav.is-solid{background:var(--green-d);box-shadow:0 2px 14px rgba(0,0,0,.18)}
.sc6-nav .sc6-wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}
.sc6-logo img{height:38px;width:auto}
.sc6-menu{display:flex;gap:28px}
.sc6-menu a{color:#fff;font-size:16px;font-weight:600;opacity:.9}
.sc6-menu a:hover{opacity:1;text-decoration:underline;text-underline-offset:6px}
.sc6-burger{display:none;position:relative;width:46px;height:46px;padding:0;margin:0;border:1.5px solid rgba(255,255,255,.55);border-radius:8px;background:transparent!important;cursor:pointer;flex:none}
.sc6-burger:hover{border-color:#fff}
.sc6-burger span{position:absolute;left:12px;right:12px;height:2px;border-radius:2px;background:#fff;transition:transform .25s,opacity .2s}
.sc6-burger span:nth-child(1){top:15px}.sc6-burger span:nth-child(2){top:21px}.sc6-burger span:nth-child(3){top:27px}
.sc6-nav.is-open .sc6-burger span:nth-child(1){transform:translateY(6px) rotate(45deg)}
.sc6-nav.is-open .sc6-burger span:nth-child(2){opacity:0}
.sc6-nav.is-open .sc6-burger span:nth-child(3){transform:translateY(-6px) rotate(-45deg)}
.sc6-nav .sc6-btn{min-height:44px;padding:10px 20px;font-size:15px;background:var(--gold);border-color:var(--gold);color:var(--green-d)!important}
.sc6-nav .sc6-btn:hover{background:#e0bf7a;border-color:#e0bf7a}

/* ===== hero ===== */
.sc6-hero{position:relative;background:var(--green-d) url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%27180%27%20height%3D%27180%27%20viewBox%3D%270%200%20180%20180%27%3E%3Cg%20fill%3D%27none%27%20stroke%3D%27%23FFFFFF%27%20stroke-width%3D%271.6%27%20stroke-linecap%3D%27round%27%20opacity%3D%270.08%27%3E%3Cline%20x1%3D%2730%27%20y1%3D%2724%27%20x2%3D%2730%27%20y2%3D%2744%27%20transform%3D%27rotate%280%2030%2034%29%27%2F%3E%3Cline%20x1%3D%2730%27%20y1%3D%2724%27%20x2%3D%2730%27%20y2%3D%2744%27%20transform%3D%27rotate%2860%2030%2034%29%27%2F%3E%3Cline%20x1%3D%2730%27%20y1%3D%2724%27%20x2%3D%2730%27%20y2%3D%2744%27%20transform%3D%27rotate%28120%2030%2034%29%27%2F%3E%3Cline%20x1%3D%27128%27%20y1%3D%27105%27%20x2%3D%27128%27%20y2%3D%27119%27%20transform%3D%27rotate%280%20128%20112%29%27%2F%3E%3Cline%20x1%3D%27128%27%20y1%3D%27105%27%20x2%3D%27128%27%20y2%3D%27119%27%20transform%3D%27rotate%2860%20128%20112%29%27%2F%3E%3Cline%20x1%3D%27128%27%20y1%3D%27105%27%20x2%3D%27128%27%20y2%3D%27119%27%20transform%3D%27rotate%28120%20128%20112%29%27%2F%3E%3C%2Fg%3E%3Cg%20fill%3D%27%23FFFFFF%27%20opacity%3D%270.08%27%3E%3Cpath%20d%3D%27M104%2025L105.4%2028.6L109%2030L105.4%2031.4L104%2035L102.6%2031.4L99%2030L102.6%2028.6Z%27%2F%3E%3Cpath%20d%3D%27M46%20134L47.12%20136.88L50%20138L47.12%20139.12L46%20142L44.88%20139.12L42%20138L44.88%20136.88Z%27%2F%3E%3Ccircle%20cx%3D%27160%27%20cy%3D%2762%27%20r%3D%271.8%27%2F%3E%3Ccircle%20cx%3D%2782%27%20cy%3D%2784%27%20r%3D%271.4%27%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E") repeat;background-size:180px 180px;color:rgba(255,255,255,.88)}
.sc6-hero .sc6-wrap{display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:clamp(32px,5vw,72px);padding:calc(var(--nav) + 32px) 0 84px}
.sc6-eyebrow{display:inline-flex;align-items:center;gap:10px;font:700 13px var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--gold)}
.sc6-eyebrow::before{content:"";width:28px;height:1.5px;background:currentColor}
.sc6-hero h1{color:#fff;font-size:clamp(40px,5.4vw,74px);line-height:1.1;margin-top:18px;text-wrap:balance}
.sc6-hero .sc6-lead{margin-top:20px;max-width:34ch;font-size:clamp(18px,1.7vw,21px)}
.sc6-hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
.sc6-hero-meta{display:flex;flex-wrap:wrap;gap:8px 26px;margin-top:24px;font-size:16px;color:rgba(255,255,255,.8)}
.sc6-hero-meta b{color:#fff;font-weight:700}
.sc6-arch{position:relative;justify-self:center;width:min(100%,460px);aspect-ratio:4/5;max-width:100%;margin:0}
.sc6-arch::before{content:"";position:absolute;inset:-14px;border:1.5px solid var(--gold);border-radius:999px 999px 22px 22px;opacity:.7}
.sc6-arch .slides{position:relative;width:100%;height:100%;overflow:hidden;border-radius:999px 999px 16px 16px;background:var(--green-d)}
.sc6-arch .slides img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 30%;opacity:0;transform:scale(1.06);transition:opacity 1.4s ease,transform 6s ease-out}
.sc6-arch .slides img.is-on{opacity:1;transform:scale(1)}
.sc6-arch figcaption{position:absolute;z-index:1;left:50%;bottom:-16px;transform:translateX(-50%);white-space:nowrap;padding:6px 16px;border-radius:999px;background:var(--gold);color:var(--green-d);font:700 13px var(--body);letter-spacing:.04em}
.sc6-arch .dots{position:absolute;left:50%;bottom:-52px;transform:translateX(-50%);display:flex;gap:10px}
.sc6-arch .dots button{width:10px;height:10px;padding:0;border-radius:50%;border:1.5px solid var(--gold);background:transparent;cursor:pointer}
.sc6-arch .dots button[aria-pressed="true"]{background:var(--gold)}
@media (prefers-reduced-motion:reduce){.sc6-arch .slides img{transition:opacity .2s;transform:none!important}}

/* bandă reducere: apare doar cât timp reducerea e activă în plugin */
.sc6-early{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:6px 14px;padding:12px 20px;background:var(--gold);color:var(--green-d)!important;font-size:16px;text-align:center}
.sc6-early b{font-weight:700}.sc6-early s{opacity:.7}
.sc6-early .go{display:inline-flex;align-items:center;gap:6px;font-weight:700;text-decoration:underline;text-underline-offset:3px}
.sc6-early svg{width:16px;height:16px;transition:transform .2s}
.sc6-early:hover svg{transform:translateX(3px)}
.sc6-pill{display:inline-block;padding:4px 12px;border-radius:999px;background:var(--gold);color:var(--green-d);font-family:var(--title);font-size:15px}

/* ===== despre ===== */
.sc6-about{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(32px,6vw,72px);align-items:center}
.sc6-about h2{font-size:clamp(30px,4vw,44px);line-height:1.15}
.sc6-about p{margin-top:16px}
.sc6-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:32px}
.sc6-fact{padding:18px 16px;border-radius:10px;background:var(--cream);text-align:center}
.sc6-fact b{display:block;font-family:var(--title);font-weight:400;font-size:34px;line-height:1;color:var(--green)}
.sc6-fact span{display:block;margin-top:8px;font-size:15px;line-height:1.35}
.sc6-about figure{border-radius:12px;overflow:hidden;aspect-ratio:4/5;background:var(--cream)}
.sc6-about figure img{width:100%;height:100%;object-fit:cover;object-position:42% 50%}

/* ===== decoruri ===== */
.sc6-decor{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.sc6-dc{background:#fff;border-radius:12px;overflow:hidden;border:1px solid var(--line)}
.sc6-dc-img{position:relative;aspect-ratio:4/5;background:var(--line);overflow:hidden}
.sc6-tag{position:absolute;top:12px;left:12px;z-index:1;padding:3px 10px;border-radius:999px;background:rgba(23,41,15,.72);color:#fff;font-size:12px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;backdrop-filter:blur(4px)}
.sc6-dc-img picture,.sc6-dc-img img{display:block;width:100%;height:100%;object-fit:cover}
.sc6-dc-body{padding:20px 22px 24px}
.sc6-dc h3{font-size:23px;line-height:1.2}
.sc6-dc p{margin-top:6px;font-size:16px}
.sc6 .sc6-note{margin-top:40px;text-align:center;font-size:16px;color:var(--muted)}

/* ===== galerie ===== */
.sc6-gal{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.sc6-gal button{position:relative;padding:0;border:0;background:var(--line);border-radius:8px;overflow:hidden;aspect-ratio:1/1;cursor:zoom-in}
.sc6-gal img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.sc6-gal button:hover img{transform:scale(1.04)}
.sc6-gal button[hidden]{display:none}
.sc6-tag--y{background:rgba(255,255,255,.85);color:var(--green-d);backdrop-filter:none}
.sc6-gal .sc6-tag{top:8px;left:8px;font-size:11px}
.sc6-filt{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin:-12px 0 26px}
.sc6-filt button{min-height:40px;padding:8px 16px;border-radius:999px;border:1px solid var(--line);background:#fff;color:var(--ink);font:600 15px var(--body);cursor:pointer;transition:background .2s,color .2s,border-color .2s}
.sc6-filt button:hover{border-color:var(--green)}
.sc6-filt button.is-on{background:var(--green);border-color:var(--green);color:#fff}
.sc6-more{margin-top:26px;text-align:center}
.sc6-more[hidden]{display:none}
#sc6More{background:var(--green)!important;border-color:var(--green)!important;color:#fff!important;opacity:1!important}
#sc6More:hover{background:var(--green-d)!important}
/* telefon: titlu și paragraf, apoi arcada, apoi butoanele; totul centrat */
@media (max-width:760px){
  .sc6-hero .sc6-wrap{grid-template-columns:1fr;gap:0;padding:calc(var(--nav) + 12px) 0 48px;text-align:center}
  .sc6-hero-txt{display:contents}
  .sc6-eyebrow{order:1;justify-self:center;gap:8px;font-size:12px;letter-spacing:.06em;white-space:nowrap}
  .sc6-eyebrow::before,.sc6-eyebrow::after{content:"";width:16px;height:1.5px;background:currentColor}
  .sc6-hero h1{order:2;margin-inline:auto}
  .sc6-hero .sc6-lead{order:3;max-width:none}
  .sc6 .sc6-arch{order:4;width:78%;margin:46px auto 76px!important}
  .sc6-hero-cta{order:5;margin-top:0;justify-content:center}
  .sc6-hero-meta{order:6;justify-content:center}
  .sc6-early{font-size:15px;padding:12px 16px}
}
}
@media (max-width:760px){.sc6-filt{flex-wrap:nowrap;justify-content:flex-start;overflow-x:auto;margin:-8px -20px 20px;padding:0 20px 4px;scrollbar-width:none}.sc6-filt::-webkit-scrollbar{display:none}.sc6-filt button{flex:0 0 auto}}

/* ===== pachete ===== */
.sc6-plans{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch}
.sc6-plan{position:relative;display:flex;flex-direction:column;border-radius:12px;background:#fff;border:2px solid var(--gold);overflow:hidden;box-shadow:0 14px 34px rgba(43,41,37,.08)}
.sc6-plan-top{padding:26px 26px 22px;text-align:center;background:var(--gold-s);border-bottom:1px solid #EADDBF}
.sc6-plan h3{font-size:24px;line-height:1.2}
.sc6-plan-sub{margin-top:4px;font-size:15px;color:var(--muted)}
.sc6-price{display:flex;align-items:baseline;justify-content:center;gap:10px;margin-top:16px}
.sc6-price b{font-family:var(--title);font-weight:400;font-size:52px;line-height:1;color:var(--ink)}
.sc6-price small{font-size:17px;font-weight:700;color:var(--ink)}
.sc6-price s{font-size:20px;font-weight:600;color:var(--muted)}
.sc6-plan ul{padding:22px 26px;flex:1}
.sc6-plan li{position:relative;padding:9px 0 9px 30px;border-bottom:1px solid #F0ECE3;font-size:17px}
.sc6-plan li:last-child{border-bottom:0}
.sc6-plan li::before{content:"";position:absolute;left:2px;top:15px;width:14px;height:8px;border-left:2.5px solid var(--green);border-bottom:2.5px solid var(--green);transform:rotate(-45deg)}
.sc6-plan-foot{display:flex;flex-direction:column;justify-content:flex-end;padding:0 26px 26px}
.sc6-plan-foot .sc6-btn{width:100%}
.sc6-plan-foot p{margin:0 0 12px;font-size:14px;line-height:1.4;text-align:center;color:#7A5E1F}
