/* programarea: titlul și formularul stau pe aceeași poză, sub un strat verde opac (ca în 2025) */
.sc6-bookwrap{position:relative;background:#1F3A17 url(/wp-content/uploads/2026/10/stefan-chelmu-decor-craciun-2026-fundal-formular-1600.webp) center/cover no-repeat!important;padding:0!important}
.sc6-bookwrap::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(23,41,15,.8) 0%,rgba(23,41,15,.88) 45%,rgba(23,41,15,.93) 100%);pointer-events:none}
.sc6-bookwrap{flex-wrap:nowrap!important}
.sc6-bookwrap>.e-con-inner,.sc6-bookwrap>.elementor-element{position:relative}
.sc6-bookwrap .sc6,.sc6-bookwrap .sc6-book{background:transparent}
@media (max-width:760px){.sc6-bookwrap{background-image:url(/wp-content/uploads/2026/10/stefan-chelmu-decor-craciun-2026-fundal-formular-m-800.webp)!important}}
/* widgeturile Elementor dintre părțile HTML: formularul și recenziile */
.elementor-element-sc6form{background:transparent;padding:0 20px clamp(64px,8vw,104px)!important}
.elementor-element-sc6form .scp{max-width:1000px}
.elementor-element-sc6form .scp-cal-dow{gap:10px!important}
.elementor-element-sc6form .scp-cal-grid{gap:10px!important;margin-top:4px}
@media (max-width:760px){.elementor-element-sc6form .scp-cal-dow{gap:6px!important}.elementor-element-sc6form .scp-cal-grid{column-gap:6px!important;row-gap:8px!important}.elementor-element-sc6form .scp .scp-day{aspect-ratio:auto;min-height:52px;padding:7px 0 8px;gap:5px}.elementor-element-sc6form .scp-day .scp-dots{max-width:26px;gap:2px 3px}}
.elementor-element-sc6form .scp-card{padding:8px clamp(18px,4vw,44px) 32px}
.elementor-element-sc6rev{padding:0 20px clamp(64px,8vw,104px)!important}
.elementor-element-sc6rev>.elementor-widget-container{max-width:1120px;margin:0 auto}
.sc6-rev-empty{max-width:1120px;margin:0 auto;padding:40px;border:2px dashed #E4DED2;border-radius:12px;text-align:center;color:#8F887B;font-family:"Source Sans Pro",Arial,sans-serif}

/* contact și hartă */
.sc6-contact-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(24px,4vw,48px);align-items:stretch}
.sc6-contact-card{padding:clamp(28px,4vw,44px);border-radius:14px;background:#fff;border:1px solid var(--line)}
.sc6-contact-card .sc6-eyebrow{color:#9A7A33}
.sc6-contact-card h2{margin-top:12px;font-size:clamp(30px,3.6vw,40px);line-height:1.15}
.sc6-clist{display:grid;gap:18px;margin-top:26px!important}
.sc6-clist li{display:flex;gap:14px;align-items:flex-start}
.sc6-clist svg{flex:none;width:22px;height:22px;margin-top:3px;fill:none;stroke:var(--green);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.sc6-clist b{display:block;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.sc6-clist span,.sc6-clist a{font-size:18px;color:var(--ink);font-weight:600}
.sc6-clist a:hover{color:var(--green)}
.sc6-contact-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}
.sc6-map{min-height:380px;border-radius:14px;overflow:hidden;background:var(--line);border:1px solid var(--line)}
.sc6-map iframe{display:block;width:100%;height:100%;min-height:380px;border:0}
@media (max-width:760px){.sc6-contact-grid{grid-template-columns:1fr}.sc6-contact-cta .sc6-btn{flex:1 1 100%}.sc6-map,.sc6-map iframe{min-height:300px}}

.sc6-foot{background:#17290F;color:rgba(255,255,255,.7);padding:28px 0;font-size:15px}
.sc6-foot .sc6-wrap{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.sc6-foot img{height:30px;width:auto}
.sc6-foot a{color:#fff}

/* bara de programare: mereu la îndemână, ascunsă cât timp formularul e pe ecran */
.sc6-bar{position:fixed;left:50%;bottom:16px;z-index:70;display:flex;gap:8px;align-items:center;padding:8px;border-radius:999px;background:#fff;box-shadow:0 10px 30px rgba(0,0,0,.22);transform:translate(-50%,150%);transition:transform .35s}
