<script>
(function(){
  var $=function(q,c){return (c||document).querySelector(q)}, $$=function(q,c){return Array.prototype.slice.call((c||document).querySelectorAll(q))};
  if(!$('#sc6')) return;

  /* ---- prețurile și reducerea, din plugin ---- */
  var MONTHS=['ianuarie','februarie','martie','aprilie','mai','iunie','iulie','august','septembrie','octombrie','noiembrie','decembrie'];
  fetch('/wp-json/scp/v1/config',{cache:'no-store',credentials:'omit'}).then(function(r){return r.ok?r.json():null}).then(function(c){
    if(!c||!c.quotes) return;
    var q=c.quotes, early=false;
    Object.keys(q).forEach(function(k){
      if(q[k].discount>0) early=true;
      $$('[data-price="'+k+'"]').forEach(function(e){e.textContent=Math.round(q[k].price)});
      $$('[data-list="'+k+'"]').forEach(function(e){e.textContent=Math.round(q[k].list)});
      $$('[data-discount="'+k+'"]').forEach(function(e){e.textContent=Math.round(q[k].discount)});
    });
    $$('[data-pay-hours]').forEach(function(e){e.textContent=c.pay_hours||48});
    $$('[data-early]').forEach(function(e){ if(early) e.removeAttribute('hidden'); else e.parentNode.removeChild(e); });
  }).catch(function(){});

  /* ---- butoanele de pachet: duc la formular și aleg pachetul ---- */
  var wanted=null;
  function applyPick(){
    if(!wanted) return true;
    var r=$('.scp input[name="package"][value="'+wanted+'"]');
    if(!r) return false;
    if(!r.disabled && !r.checked){ r.checked=true; r.dispatchEvent(new Event('change',{bubbles:true})); }
    wanted=null; return true;
  }
  $$('[data-pick]').forEach(function(a){
    a.addEventListener('click',function(){
      wanted=a.getAttribute('data-pick');
      try{ window.dataLayer=window.dataLayer||[]; window.dataLayer.push({event:'sc6_pick',scp_package:wanted}); }catch(e){}
      if(!applyPick()){ var n=0, t=setInterval(function(){ if(applyPick()||++n>40) clearInterval(t) },150); }
    });
  });
  // linkuri din reclame sau postări: ...#programare?pachet=foto_plus  sau  ?pachet=foto
  var m=(location.search+location.hash).match(/pachet=(foto_plus|foto)/);
  if(m){ wanted=m[1]; var n0=0, t0=setInterval(function(){ if(applyPick()||++n0>60) clearInterval(t0) },200); }

  /* ---- meniu și bara de programare ---- */
  var nav=$('#sc6Nav'), bar=$('#sc6Bar'), hero=$('.sc6-hero'), formEl=null;
  function onScroll(){
    var y=window.scrollY||window.pageYOffset, vh=window.innerHeight;
    nav.classList.toggle('is-solid',y>30);
    formEl=formEl||$('.elementor-element-sc6form')||$('.scp');
    var head=$('#programare'), top=head?head.getBoundingClientRect().top:1e9;
    var bottom=formEl?formEl.getBoundingClientRect().bottom:-1;
    var formOnScreen=top<vh*.85 && bottom>vh*.15;
    bar.classList.toggle('is-on', y>(hero?hero.offsetHeight*.6:300) && !formOnScreen);
  }
  var burger=$('#sc6Burger');
  function menu(open){ nav.classList.toggle('is-open',open); burger.setAttribute('aria-expanded',String(open)); burger.setAttribute('aria-label',open?'Închide meniul':'Deschide meniul'); }
  if(burger){
    burger.addEventListener('click',function(){ menu(!nav.classList.contains('is-open')) });
    $$('#sc6Menu a').forEach(function(a){ a.addEventListener('click',function(){ menu(false) }) });
    document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&nav.classList.contains('is-open')){ menu(false); burger.focus() } });
    document.addEventListener('click',function(e){ if(nav.classList.contains('is-open')&&!nav.contains(e.target)) menu(false) });
    window.addEventListener('resize',function(){ if(window.innerWidth>1020) menu(false) });
  }
  window.addEventListener('scroll',onScroll,{passive:true}); window.addEventListener('resize',onScroll); onScroll();

  /* ---- hero: decorurile se schimbă pe rând în arcadă ---- */
  var arch=$('#sc6Arch');
  if(arch){
    var ims=$$('.slides img',arch), dts=$$('.dots button',arch), nm=$('.nm',arch), ai=0, at=null;
    var still=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    function sh(n){ ai=(n+ims.length)%ims.length; ims.forEach(function(im,k){im.classList.toggle('is-on',k===ai)}); dts.forEach(function(d,k){d.setAttribute('aria-pressed',String(k===ai))}); nm.textContent=ims[ai].getAttribute('data-name'); }
    function pl(){ if(still) return; st(); at=setInterval(function(){sh(ai+1)},5000); }
    function st(){ if(at){clearInterval(at);at=null} }
    dts.forEach(function(d,k){ d.addEventListener('click',function(){sh(k);pl()}) });
    arch.addEventListener('mouseenter',st); arch.addEventListener('mouseleave',pl);
    document.addEventListener('visibilitychange',function(){ document.hidden?st():pl() });
    pl();
  }

  /* ---- întrebări ---- */
  $$('#sc6Faq .sc6-qa').forEach(function(q){
    var b=$('button',q);
    b.addEventListener('click',function(){
      var open=!q.classList.contains('is-open');
      $$('#sc6Faq .sc6-qa').forEach(function(x){ x.classList.remove('is-open'); $('button',x).setAttribute('aria-expanded','false'); });
      if(open){ q.classList.add('is-open'); b.setAttribute('aria-expanded','true'); }
    });
  });

  /* ---- galerie: filtre pe ani, primele 12 la început, lightbox pe pozele vizibile ---- */
  var gal=$('#sc6Gal'), all=$$('#sc6Gal button'), more=$('#sc6More'), filt='all', expanded=false, LIMIT=12;
  function visible(){ return all.filter(function(b){ return !b.hidden }); }
  function apply(){
    var n=0, total=0;
    all.forEach(function(b){
      var ok = filt==='all' || b.getAttribute('data-y')===filt;
      if(ok) total++;
      b.hidden = !ok || (filt==='all' && !expanded && n>=LIMIT);
      if(ok) n++;
    });
    more.parentNode.hidden = !(filt==='all' && !expanded && total>LIMIT);
    more.textContent='Arată toate fotografiile ('+total+')';
  }
  $$('.sc6-filt button').forEach(function(c){
    c.addEventListener('click',function(){
      filt=c.getAttribute('data-f');
      $$('.sc6-filt button').forEach(function(x){ var on=x===c; x.classList.toggle('is-on',on); x.setAttribute('aria-pressed',on?'true':'false'); });
      apply();
    });
  });
  more.addEventListener('click',function(){ expanded=true; apply(); });
  apply();
  var lb=$('#sc6Lb'), lbi=$('img',lb), items=[], idx=0;
  function show(){ var b=items[idx], im=$('img',b); lbi.src=b.getAttribute('data-full')||im.currentSrc||im.src; lbi.alt=im.alt; }
  function open(b){ items=visible(); idx=Math.max(0,items.indexOf(b)); show(); lb.classList.add('is-open'); document.documentElement.style.overflow='hidden'; $('.x',lb).focus(); }
  function close(){ lb.classList.remove('is-open'); document.documentElement.style.overflow=''; if(items[idx]) items[idx].focus(); }
  function step(d){ idx=(idx+d+items.length)%items.length; show(); }
  all.forEach(function(b){ b.addEventListener('click',function(){open(b)}) });
  $('.x',lb).onclick=close; $('.p',lb).onclick=function(){step(-1)}; $('.n',lb).onclick=function(){step(1)};
  lb.addEventListener('click',function(e){ if(e.target===lb) close(); });
  document.addEventListener('keydown',function(e){ if(!lb.classList.contains('is-open')) return; if(e.key==='Escape') close(); if(e.key==='ArrowLeft') step(-1); if(e.key==='ArrowRight') step(1); });
  var tx=0; lb.addEventListener('touchstart',function(e){tx=e.touches[0].clientX},{passive:true});
  lb.addEventListener('touchend',function(e){ var d=e.changedTouches[0].clientX-tx; if(Math.abs(d)>50) step(d<0?1:-1); });

  /* ---- măsurare: doar în dataLayer; din GTM pleacă mai departe, după consimțământ ---- */
  $$('[data-ev="voucher"]').forEach(function(a){ a.addEventListener('click',function(){ try{ window.dataLayer=window.dataLayer||[]; window.dataLayer.push({event:'sc6_voucher',scp_link:a.getAttribute('href')}); }catch(e){} }); });
  $$('[data-ev="call"]').forEach(function(a){ a.addEventListener('click',function(){ try{ window.dataLayer=window.dataLayer||[]; window.dataLayer.push({event:'sc6_call'}); }catch(e){} }); });
})();
</script>
